import {buildIndex,modelMessages} from './document-engine.mjs';
import {readDocument,MAX_TOTAL,MAX_FILES} from './document-reader.mjs';
import {listDocuments,saveDocument,removeDocument,clearDocuments} from './document-store.mjs';
const $=id=>document.getElementById(id),node=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
let owner=null,documents=[],index=buildIndex([]),epoch=0,busy=false,persistent=true,engine=null,modelWorker=null,modelEpoch=0,loadingModel=false,cancelLoad=null,questionAbort=null,answerVersion=0;
const status=text=>$('documentStatus').textContent=text;
function controls(){$('documentFiles').disabled=!owner||busy;document.querySelectorAll('#documentList button').forEach(b=>b.disabled=busy);$('clearDocuments').disabled=!owner||busy||!documents.length;$('askDocuments').disabled=!owner||busy||!documents.length;$('stopAnswer').disabled=!questionAbort;$('enableModel').disabled=loadingModel||!!engine||busy;$('disableModel').disabled=!engine&&!loadingModel;$('documentScope').textContent=owner?(owner==='guest'?'Misafir belgeleri · Bu cihaz':'Kişisel belgeler · Bu cihaz'):'Hesap durumu yükleniyor…';$('documentCount').textContent=documents.length+' belge · '+index.count+' metin bölümü';}
function resetAnswer(){answerVersion++;questionAbort?.abort();questionAbort=null;engine?.interruptGenerate();$('documentAnswer').replaceChildren();}
function stopModel(){modelEpoch++;cancelLoad?.();cancelLoad=null;modelWorker?.terminate();modelWorker=null;engine=null;loadingModel=false;$('modelStatus').textContent='Kaynak taraması açık. Yerel dil modeli kapalı.';controls();}
function rebuild(){index=buildIndex(documents);const list=$('documentList');list.replaceChildren();for(const doc of documents){const item=node('article',null,'document-item'),name=node('div');name.append(node('b',doc.name),node('small',doc.pages.length+' sayfa/bölüm · '+doc.characters.toLocaleString('tr-TR')+' karakter'));const remove=node('button','Sil');remove.disabled=busy;remove.onclick=async()=>{if(busy)return;busy=true;resetAnswer();stopModel();controls();const target=owner,id=epoch;try{if(persistent)await removeDocument(target,doc.id);if(id!==epoch)return;documents=documents.filter(d=>d.id!==doc.id);rebuild();status('Belge silindi; kaynak dizini güncellendi.');}catch(e){status(e.message);}finally{if(id===epoch){busy=false;rebuild();controls();}}};item.append(name,remove);list.append(item);}controls();}
async function switchOwner(next){const id=++epoch;resetAnswer();stopModel();owner=null;documents=[];busy=false;rebuild();try{const saved=await listDocuments(next);if(id!==epoch)return;documents=saved;persistent=true;status('Belgeler bu cihazda saklanır; sunucuya gönderilmez.');}catch{if(id!==epoch)return;persistent=false;status('Kalıcı tarayıcı depolaması açılamadı. Belgeler yalnızca bu açık oturumda tutulacak.');}if(id===epoch){owner=next;rebuild();}}
window.addEventListener('accountchange',e=>void switchOwner(e.detail?.owner||'guest'));
$('documentFiles').onchange=async e=>{const files=[...e.target.files];e.target.value='';if(!owner||busy||!files.length)return;const id=epoch,target=owner;busy=true;resetAnswer();controls();const messages=[];for(const file of files){if(id!==epoch)break;try{if(documents.length>=MAX_FILES)throw new Error('En fazla '+MAX_FILES+' belge eklenebilir.');status(file.name+' okunuyor…');const doc=await readDocument(file);if(id!==epoch)break;if(documents.some(d=>d.id===doc.id)){messages.push(file.name+': zaten ekli.');continue;}if(documents.reduce((n,d)=>n+d.characters,0)+doc.characters>MAX_TOTAL)throw new Error('Toplam metin sınırı 1.000.000 karakter.');if(persistent)await saveDocument(target,doc);if(id!==epoch)break;documents.push(doc);messages.push(file.name+': eklendi.');}catch(error){if(id===epoch)messages.push(file.name+': '+error.message);}}if(id===epoch){busy=false;rebuild();status(messages.join(' '));}};
$('clearDocuments').onclick=async()=>{if(busy||!documents.length||!confirm('Bu kullanıcıya ait bu cihazdaki tüm belgeler silinsin mi?'))return;const id=epoch,target=owner;busy=true;resetAnswer();stopModel();controls();try{if(persistent)await clearDocuments(target);if(id!==epoch)return;documents=[];rebuild();status('Bu cihazdaki belgelerin tamamı silindi.');}catch(e){status(e.message);}finally{if(id===epoch){busy=false;rebuild();controls();}}};
$('enableModel').onclick=async()=>{if(engine||loadingModel||busy)return;loadingModel=true;const id=++modelEpoch;controls();$('modelStatus').textContent='Cihaz desteği kontrol ediliyor…';try{if(!navigator.gpu)throw new Error('WebGPU bulunamadı. Kaynak taraması çalışmaya devam ediyor.');const adapter=await navigator.gpu.requestAdapter();if(id!==modelEpoch)return;if(!adapter||!adapter.features.has('shader-f16'))throw new Error('Bu GPU yerel modeli desteklemiyor. Kaynak taramasını kullanabilirsin.');const lib=await import('./vendor/webllm.mjs');if(id!==modelEpoch)return;modelWorker=new Worker(new URL('./model-worker.mjs',import.meta.url),{type:'module'});const cancelled=new Promise((_,reject)=>cancelLoad=()=>reject(new DOMException('İptal edildi','AbortError')));const loaded=await Promise.race([lib.CreateWebWorkerMLCEngine(modelWorker,'Qwen2.5-0.5B-Instruct-q4f16_1-MLC',{initProgressCallback:p=>{if(id===modelEpoch)$('modelStatus').textContent=p.text||'Model indiriliyor…';}},{context_window_size:2048}),cancelled]);if(id!==modelEpoch)return;engine=loaded;$('modelStatus').textContent='Qwen2.5 0.5B hazır · Yanıtlar bu cihazda üretilir.';}catch(error){if(id===modelEpoch){modelWorker?.terminate();modelWorker=null;engine=null;$('modelStatus').textContent=error.name==='AbortError'?'Model yükleme iptal edildi.':error.message+' Kaynak taraması kullanılabilir.';}}finally{if(id===modelEpoch){loadingModel=false;cancelLoad=null;controls();}}};
$('disableModel').onclick=()=>{resetAnswer();stopModel();};
$('stopAnswer').onclick=()=>{questionAbort?.abort();engine?.interruptGenerate();};
function abortable(promise,signal){return Promise.race([promise,new Promise((_,reject)=>{if(signal.aborted)reject(new DOMException('İptal edildi','AbortError'));else signal.addEventListener('abort',()=>reject(new DOMException('İptal edildi','AbortError')),{once:true});})]);}
$('documentQuestionForm').onsubmit=async e=>{e.preventDefault();if(busy||!owner||!documents.length)return;resetAnswer();const id=epoch,version=answerVersion,question=$('documentQuestion').value.trim(),sources=index.search(question),out=$('documentAnswer');if(!sources.length){out.append(node('h3','Belgelerde yeterli kaynak bulunamadı'),node('p','Soruda geçen konuyu içeren bir belge ekle veya daha belirgin bir soru sor.'));return;}busy=true;questionAbort=new AbortController();const signal=questionAbort.signal;controls();out.append(node('h3',engine?'Yerel model yanıtı hazırlanıyor…':'Belgelerden bulunan bilgiler'));const sourcesBox=node('div',null,'document-sources');sources.forEach((source,i)=>{const card=node('article',null,'document-source');card.append(node('b','['+(i+1)+'] '+source.name+(source.page?' · s. '+source.page:' · bölüm '+source.part)),node('blockquote',source.text));sourcesBox.append(card);});out.append(sourcesBox);
try{if(engine){const reply=await abortable(engine.chat.completions.create({messages:modelMessages(question,sources.map(s=>({...s,text:s.text.slice(0,600)}))),temperature:.1,max_tokens:320,stream:false}),signal);if(id!==epoch||version!==answerVersion||signal.aborted)return;const answer=reply.choices?.[0]?.message?.content;if(!answer)throw new Error('Model yanıt üretmedi.');out.querySelector('h3').textContent='Yerel modelin belgeye dayalı yanıtı';out.insertBefore(node('p',answer,'generated-answer'),sourcesBox);}out.append(node('p',engine?'Küçük dil modeli hata yapabilir. Yanıtı yukarıdaki asıl belge alıntılarıyla kontrol et.':'Bu görünüm bir dil modeli yanıtı değil; belgelerdeki ilgili bölümlerin kaynaklı taramasıdır.','hint'));}catch(error){if(id===epoch&&version===answerVersion){out.querySelector('h3').textContent='Belge kaynakları';out.append(node('p',error.name==='AbortError'?'Yanıt üretimi durduruldu.':error.message+' Kaynak bölümlerini okuyabilirsin.','hint'));}}finally{if(id===epoch){busy=false;questionAbort=null;controls();rebuild();}}};
controls();

const drop=document.getElementById('documentDrop');drop.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!document.getElementById('documentFiles').disabled){e.preventDefault();document.getElementById('documentFiles').click();}};drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();const input=document.getElementById('documentFiles');if(!input.disabled){input.files=e.dataTransfer.files;input.onchange({target:input});}};

window.addEventListener('viewchange',e=>{if(e.detail!=='assistant'&&questionAbort){questionAbort.abort();engine?.interruptGenerate();}});
